package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"
)

func readLine() string {
	reader := bufio.NewReader(os.Stdin)
	line, err := reader.ReadString('\n')
	if err != nil {
		panic("QQ")
	}
	return strings.TrimSpace(line)
}

func main() {
	ans := uint32(1)
	nStr := readLine()
	n64, err := strconv.ParseUint(nStr, 10, 32)
	if err != nil {
		panic(err)
	}
	n := uint32(n64)

	for i := uint32(1); i < n; i++ {
		ans = ans * (i + n - 1) / i
	}
	fmt.Println(ans)
}

